INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '至少一个', 'kp-pb-cp-at-least', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "“至少”问题与对立事件"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "最高频法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "正难则反！看到“至少”，立马去算它的反面“一个都不”。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“射击 3 次，至少命中 1 次的概率是多少？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“至少命中 1 次”包含了：中1次、中2次、中3次。正面去算不仅要分类还要相加，极其繁琐。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "它的反面（对立事件）是唯一的：【3 次全部脱靶】！"}]}, {"type": "katexBlock", "attrs": {"content": "P(\\text{至少一个}) = 1 - P(\\text{一个都不})"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、例题推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 命中率 0.6。射击 3 次，至少命中 1 次的概率？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "找反面：“一次都没命中”。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算反面概率：脱靶率 = 1 - 0.6 = 0.4。连续 3 次脱靶 = 0.4 × 0.4 × 0.4 = 0.064。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "用 1 减去反面：1 - 0.064 = 0.936（即 93.6%）。秒杀！"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "忘记用 1 去减：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "历尽千辛万苦算出了反面的概率 0.064，激动地在选项里找，命题人一定准备了 A. 0.064 等着你。这叫为他人作嫁衣裳。算完反面，立刻用 1 去减！"}]}]}]}$$ AS jsonb), NULL, '至少一个的核心考点与实战推导。', category_node.id, CAST('["数量关系", "概率问题", "至少一个"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pb_cp_at_least", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
